      m_physic.set_velocity_y(HEAVYCOIN_WATER_SINK_SPEED * gravity_sign);
      m_col.set_movement(Vector(m_col.get_movement().x, HEAVYCOIN_WATER_SINK_SPEED * gravity_sign * dt_sec));
    }
  }
}''')
